// spendemic.c// SPENDEMIC - Track the damage.#include <stdio.h>#include <string.h>#include <time.h>#define MAX 100typedef struct {    int id;    float amount;    char desc[50];    char category[20];} Expense;Expense e[MAX];int count = 0;float budget = 0;/* Removes the newline added by fgets() */void clean(char s[]) {    s[strcspn(s, "\n")] = '\0';}/* Rule-based Auto-Bifurcation */void classify(char desc[], char category[]) {    if (strstr(desc, "uber") || strstr(desc, "bus") ||        strstr(desc, "auto"))        strcpy(category, "Transport");    else if (strstr(desc, "food") || strstr(desc, "pizza") ||             strstr(desc, "cafe"))        strcpy(category, "Food");    else if (strstr(desc, "book") || strstr(desc, "course"))        strcpy(category, "Education");    else if (strstr(desc, "movie") || strstr(desc, "game"))        strcpy(category, "Entertainment");    else if (strstr(desc, "medicine") || strstr(desc, "doctor"))        strcpy(category, "Medical");    else        strcpy(category, "Miscellaneous");}/* Save everything to a simple text file */void saveData() {    FILE *fp = fopen("expenses.txt", "w");    if (fp == NULL) {        printf("Could not save data!\n");        return;    }    fprintf(fp, "%.2f\n%d\n", budget, count);    for (int i = 0; i < count; i++)        fprintf(fp, "%d|%.2f|%s|%s\n",                e[i].id, e[i].amount, e[i].desc, e[i].category);    fclose(fp);}/* Load previous data when program starts */void loadData() {    FILE *fp = fopen("expenses.txt", "r");    if (fp == NULL)        return;                     // First run: no file yet    fscanf(fp, "%f\n%d\n", &budget, &count);    if (count > MAX)        count = MAX;    for (int i = 0; i < count; i++)        fscanf(fp, "%d|%f|%49[^|]|%19[^\n]\n",               &e[i].id, &e[i].amount, e[i].desc, e[i].category);    fclose(fp);}float totalSpent() {    float total = 0;    for (register int i = 0; i < count; i++)        total += e[i].amount;    return total;}void addExpense() {    if (count >= MAX) {        printf("\nExpense storage is full!\n");        return;    }    printf("Description: ");    fgets(e[count].desc, sizeof(e[count].desc), stdin);    clean(e[count].desc);    printf("Amount: Rs ");    scanf("%f", &e[count].amount);    getchar();    if (e[count].amount <= 0) {        printf("Invalid amount!\n");        return;    }    e[count].id = count + 1;    classify(e[count].desc, e[count].category);    printf("\nAuto-Bifurcation -> %s\n", e[count].category);    count++;    saveData();    printf("Expense added successfully!\n");}void viewExpenses() {    printf("\n------------- TRANSACTIONS -------------\n");    if (count == 0) {        printf("No transactions yet.\n");        return;    }    for (int i = 0; i < count; i++)        printf("#%d  Rs %-8.2f %-15s %s\n",               e[i].id, e[i].amount,               e[i].category, e[i].desc);}void dashboard() {    float spent = totalSpent();    printf("\n=============== SPENDEMIC ===============\n");    printf("            TRACK THE DAMAGE\n");    printf("-----------------------------------------\n");    printf("Monthly Budget : Rs %.2f\n", budget);    printf("Damage Done    : Rs %.2f\n", spent);    printf("Money Left     : Rs %.2f\n", budget - spent);    printf("Transactions   : %d\n", count);    if (budget > 0)        printf("Budget Used    : %.1f%%\n", spent / budget * 100);}void detector() {    if (count == 0) {        printf("\nNothing to analyse yet.\n");        return;    }    float average = totalSpent() / count;    printf("\n========== EXPENSE DETECTOR ==========\n");    for (int i = 0; i < count; i++) {        if (e[i].amount > average * 2)            printf("! #%d is unusually large: Rs %.2f\n",                   e[i].id, e[i].amount);        for (int j = i + 1; j < count; j++)            if (e[i].amount == e[j].amount)                printf("! #%d and #%d have identical amounts.\n",                       e[i].id, e[j].id);    }}void afford() {    float price;    float remaining = budget - totalSpent();    printf("\nPlanned purchase: Rs ");    scanf("%f", &price);    getchar();    printf("\nRemaining budget: Rs %.2f\n", remaining);    if (price > remaining)        printf("[NO] UNAFFORDABLE - exceeds remaining budget.\n");    else if (price > remaining * 0.50)        printf("[!] RISKY - consumes over 50%% of money left.\n");    else        printf("[OK] SAFE - purchase is within a reasonable limit.\n");}void forecast() {    time_t now = time(NULL);    struct tm *today = localtime(&now);    int day = today->tm_mday;    float spent = totalSpent();    if (day <= 0 || spent == 0) {        printf("\nNot enough spending data.\n");        return;    }    float daily = spent / day;    float projected = daily * 30;    printf("\n========= SURVIVAL FORECAST =========\n");    printf("Day of month       : %d\n", day);    printf("Daily spending     : Rs %.2f\n", daily);    printf("Projected spending : Rs %.2f\n", projected);    if (projected > budget)        printf("[DANGER] Budget may not survive the month!\n");    else        printf("[SAFE] Budget is currently on track.\n");}void timeline() {    printf("\n========== SPENDING TIMELINE ==========\n");    for (int i = 0; i < count; i++) {        printf("#%-3d Rs %-8.2f | ", e[i].id, e[i].amount);        int bars = (int)(e[i].amount / 100);        if (bars > 20) bars = 20;        for (int j = 0; j < bars; j++)            printf("#");        printf("\n");    }}void undo() {    if (count == 0) {        printf("\nNothing to undo!\n");        return;    }    printf("\nRemoving #%d: %s (Rs %.2f)\n",           e[count - 1].id,           e[count - 1].desc,           e[count - 1].amount);    count--;    saveData();    printf("Last transaction undone.\n");}int main() {    int choice;    loadData();    do {        dashboard();        printf("\n1. Set Monthly Budget");        printf("\n2. Add Expense");        printf("\n3. View Transactions");        printf("\n4. Expense Detector");        printf("\n5. Can I Afford This?");        printf("\n6. Budget Survival Forecast");        printf("\n7. Spending Timeline");        printf("\n8. Undo Last Transaction");        printf("\n9. Exit");        printf("\n\nChoose: ");        if (scanf("%d", &choice) != 1) {            while (getchar() != '\n');            printf("Please enter a number!\n");            continue;        }        getchar();        switch (choice) {            case 1:                printf("Enter monthly budget: Rs ");                scanf("%f", &budget);                getchar();                if (budget < 0)                    budget = 0;                saveData();                break;            case 2: addExpense();   break;            case 3: viewExpenses(); break;            case 4: detector();     break;            case 5: afford();       break;            case 6: forecast();     break;            case 7: timeline();     break;            case 8: undo();         break;            case 9:                saveData();                printf("\nSPENDEMIC closed. Damage recorded :)\n");                break;            default:                printf("\nInvalid choice!\n");        }    } while (choice != 9);    return 0;}